sub(r'function gameCard\(g\)\{.*?\nfunction bindGameActions\(root\)\{.*?\}', r'''function gameCard(g){const d=gameDate(g),rink=g.location?.trim()||'',fav=state.favoriteRinks.has(rink),hasStats=live(g)||stat(g)==='final';return`<article class="gamecard${live(g)?' live':''}${hasStats?' has-stats':''}" ${hasStats?`data-stats-game="${escAttr(g.gameId)}" role="button" tabindex="0" aria-label="Open stats for ${escAttr(g.visitor?.title||'Visitor')} versus ${escAttr(g.home?.title||'Home')}"`:''}><div class="ghead"><div><strong>${esc(fmtDate(d))}</strong><div class="muted">${esc(fmtTime(d))}</div></div>${badge(g)}</div><div class="teams"><div class="trow">${logo(g.visitor,'sm')}<div><div class="tname">${esc(g.visitor?.title||'Visitor')}</div><div class="side">Away</div></div><div class="score">${stat(g)==='scheduled'?'—':esc(g.visitor?.goals??'')}</div></div><div class="trow">${logo(g.home,'sm')}<div><div class="tname">${esc(g.home?.title||'Home')}</div><div class="side">Home</div></div><div class="score">${stat(g)==='scheduled'?'—':esc(g.home?.goals??'')}</div></div></div><div class="gmeta"><div><div class="mk">Division</div><div class="mv">${esc(division(g))}</div></div><div><div class="mk">Rink</div><div class="mv"><button class="star${fav?' active':''}" data-rink="${escAttr(rink)}">${fav?'★':'☆'}</button> ${esc(rink||'—')}</div></div><div><div class="mk">Game</div><div class="mv">${esc(g.number||g.gameId)}</div></div></div><div class="gfoot"><a class="link" target="_blank" rel="noopener" href="https://gamesheetstats.com/seasons/${state.seasonId}/games/${g.gameId}">GameSheet ↗</a>${hasStats?`<div class="footer-actions"><span class="stats-hint">Stats available ›</span><button class="rowbtn stats" data-game="${g.gameId}">Stats</button></div>`:'<span class="muted">Scheduled</span>'}</div></article>`}
function bindGameActions(root){root.querySelectorAll('.star').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleRink(b.dataset.rink)});root.querySelectorAll('.stats').forEach(b=>b.onclick=e=>{e.stopPropagation();openStats(b.dataset.game)});root.querySelectorAll('.gamecard[data-stats-game]').forEach(card=>{const open=()=>openStats(card.dataset.statsGame);card.onclick=e=>{if(e.target.closest('a,button,input,select,label'))return;open()};card.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&!e.target.closest('a,button,input,select,label')){e.preventDefault();open()}}})}''', 'gameCard/bindGameActions')

sub(r'function scheduleTeamGroups\(divisionId\)\{.*?\nfunction whenMatch\(g,m,now\)', r'''function scheduleTeamGroups(divisionId){const teams=divisionId?state.teams.filter(t=>t.divisions.has(String(divisionId))):state.teams,groups=new Map();for(const t of teams){const divTitles=[...t.divisions].map(id=>state.divisions.find(d=>String(d.id)===String(id))?.title).filter(Boolean).sort(),divLabel=divisionId?(state.divisions.find(d=>String(d.id)===String(divisionId))?.title||''):divTitles.join(' / '),key=`${normalize(t.title)}|${normalize(divLabel)}`;if(!groups.has(key))groups.set(key,{ids:[],title:t.title,divisionTitle:divLabel});groups.get(key).ids.push(String(t.id))}return[...groups.values()].sort((a,b)=>a.title.localeCompare(b.title,undefined,{numeric:true}))}
function refreshScheduleResults(){const games=scheduleGames(),count=$('#scheduleCount'),root=$('#scheduleGames');if(count)count.textContent=`${games.length} games`;if(root){root.innerHTML=games.map(gameCard).join('')||'<div class="panel empty">No games match these filters.</div>';bindGameActions(root)}pollLive()}
function renderSchedule(){const s=state.schedule,divOpts=state.divisions.map(d=>`<option value="${d.id}" ${String(d.id)===String(s.division)?'selected':''}>${esc(d.title)}</option>`).join(''),groups=scheduleTeamGroups(s.division),selectedIds=String(s.team||'').split(',').filter(Boolean),teamOpts=groups.map(g=>{const selected=g.ids.some(id=>selectedIds.includes(id)),label=s.division?g.title:(g.divisionTitle?`${g.title} — ${g.divisionTitle}`:g.title);return`<option value="${escAttr(g.ids.join(','))}" ${selected?'selected':''}>${esc(label)}</option>`}).join(''),rinks=[...new Set(state.games.map(g=>String(g.location||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true})),games=scheduleGames();els.scheduleView.innerHTML=`<div class="heading"><div><h1>Schedule</h1><p>Full league schedule and filters.</p></div><div id="scheduleCount" class="count">${games.length} games</div></div><section class="panel filters"><div class="filtergrid"><div><label class="label">Division</label><select id="fDiv"><option value="">All divisions</option>${divOpts}</select></div><div><label class="label">Team</label><select id="fTeam"><option value="">All teams</option>${teamOpts}</select></div><div><label class="label">When</label><select id="fWhen"><option value="upcoming" ${s.when==='upcoming'?'selected':''}>Upcoming</option><option value="today" ${s.when==='today'?'selected':''}>Today</option><option value="weekend" ${s.when==='weekend'?'selected':''}>This weekend</option><option value="next7" ${s.when==='next7'?'selected':''}>Next 7 days</option><option value="all" ${s.when==='all'?'selected':''}>Entire season</option></select></div><div><label class="label">Rink</label><select id="fRink"><option value="">All rinks</option>${rinks.map(r=>`<option value="${escAttr(r)}" ${normalize(r)===normalize(s.rink)?'selected':''}>${esc(r)}</option>`).join('')}</select></div><div class="wide"><label class="label">Search</label><input id="fSearch" type="search" value="${escAttr(s.search)}" placeholder="PNY september 13"></div></div><div class="checkrow"><label><input id="fMine" type="checkbox" ${s.myTeam?'checked':''}> My Team only</label><label><input id="fFav" type="checkbox" ${s.faves?'checked':''}> Favorite venues only</label><label><input id="fSched" type="checkbox" ${s.scheduled?'checked':''}> Scheduled only</label><button id="setTeamFromFilter" class="soft" ${s.team?'':'disabled'}>Set selected team as My Team</button><button id="clearScheduleFilters" class="soft">Clear filters</button></div></section><div id="scheduleGames" class="list">${games.map(gameCard).join('')||'<div class="panel empty">No games match these filters.</div>'}</div>`;bindGameActions(els.scheduleView);$('#fDiv').onchange=()=>{state.schedule.division=$('#fDiv').value;state.schedule.team='';renderSchedule()};$('#fTeam').onchange=()=>{state.schedule.team=$('#fTeam').value;$('#setTeamFromFilter').disabled=!state.schedule.team;refreshScheduleResults()};$('#fRink').onchange=()=>{state.schedule.rink=$('#fRink').value;refreshScheduleResults()};$('#fWhen').onchange=()=>{state.schedule.when=$('#fWhen').value;refreshScheduleResults()};$('#fMine').onchange=()=>{state.schedule.myTeam=$('#fMine').checked;refreshScheduleResults()};$('#fFav').onchange=()=>{state.schedule.faves=$('#fFav').checked;refreshScheduleResults()};$('#fSched').onchange=()=>{state.schedule.scheduled=$('#fSched').checked;refreshScheduleResults()};$('#fSearch').oninput=()=>{state.schedule.search=$('#fSearch').value;refreshScheduleResults()};$('#setTeamFromFilter').onclick=()=>{const ids=String(state.schedule.team||'').split(',').filter(Boolean);if(!ids.length)return;state.myTeamBySeason[state.seasonId]=ids[0];savePrefs();refreshScheduleResults()};$('#clearScheduleFilters').onclick=()=>{state.schedule={division:'',team:'',rink:'',when:'upcoming',search:'',myTeam:false,faves:false,scheduled:false};renderSchedule()}}
function scheduleGames(){const s=state.schedule,now=new Date(),q=normalize(s.search),teamIds=String(s.team||'').split(',').filter(Boolean),rinkWanted=normalize(s.rink);return state.games.filter(g=>{if(s.division&&!new Set([g.home?.division?.id,g.visitor?.division?.id].filter(Boolean).map(String)).has(String(s.division)))return false;if(teamIds.length&&!teamIds.some(id=>hasTeam(g,id)))return false;if(s.rink){const loc=String(g.location||'').trim();if(!loc||normalize(loc)!==rinkWanted)return false}if(s.myTeam&&!hasTeam(g,myTeamId()))return false;if(s.faves&&!state.favoriteRinks.has(String(g.location||'').trim()))return false;if(s.scheduled&&stat(g)!=='scheduled')return false;if(!whenMatch(g,s.when,now))return false;return searchMatch(g,q)}).sort((a,b)=>gameDate(a)-gameDate(b))}
function whenMatch(g,m,now)''', 'schedule functions')

sub(r'function venueCard\(r,mine\)\{.*?\nfunction favPlayerMap', r'''function venueCard(r,mine){let games=state.games.filter(g=>g.location?.trim()===r&&venueWindow(g));if(state.venueMyTeam)games=games.filter(g=>hasTeam(g,mine));games.sort((a,b)=>gameDate(a)-gameDate(b));const myCount=state.games.filter(g=>g.location?.trim()===r&&hasTeam(g,mine)&&gameDate(g)>=new Date()).length;return`<section class="venuecard"><div class="venuehead"><div style="display:flex;gap:10px"><div class="venueicon">◫</div><div><h3>${esc(r)}</h3><div class="muted">Favorite venue</div></div></div><button class="star active unstar" data-rink="${escAttr(r)}">★</button></div><div class="venuemeta"><span class="pill">${games.length} in view</span>${mine?`<span class="pill">My Team: ${myCount} upcoming</span>`:''}</div><div class="venuegames">${games.slice(0,5).map(g=>{const hs=live(g)||stat(g)==='final';return`<div class="venuegame${hs?' clickable':''}" ${hs?`data-venue-stats="${escAttr(g.gameId)}"`:''}><div><b>${esc(fmtDate(gameDate(g)).split(',')[0])}</b><div class="time">${esc(fmtTime(gameDate(g)))}</div></div><div class="match">${esc(g.visitor?.title||'')} vs ${esc(g.home?.title||'')}</div><button class="rowbtn ${hs?'stats':'game-open'}" ${hs?`data-game="${g.gameId}"`:`data-url="https://gamesheetstats.com/seasons/${state.seasonId}/games/${g.gameId}"`}>${hs?'Stats':'Game'}</button></div>`}).join('')||'<div class="empty" style="padding:16px">No games in this window.</div>'}</div><div class="actions"><button class="soft viewvenue" data-rink="${escAttr(r)}">View full venue schedule</button></div></section>`}
function favPlayerMap''', 'venue card')

sub(r'async function openPlayerPicker\(\)\{.*?\nfunction renderPlayerPicker\(\)\{.*?\}', r'''function playerTeamOptions(divisionId){const teams=state.teams.filter(t=>!divisionId||t.divisions.has(String(divisionId))),seen=new Map();for(const t of teams){const key=normalize(t.title);if(!seen.has(key))seen.set(key,{ids:[],title:t.title});seen.get(key).ids.push(t.id)}return[...seen.values()].sort((a,b)=>a.title.localeCompare(b.title,undefined,{numeric:true}))}
async function openPlayerPicker(){openDrawer('Add Players','Choose players to follow','<div class="muted">Loading…</div>');const t=myTeam(),myDiv=t?[...t.divisions][0]:'',teams=playerTeamOptions(myDiv),myGroup=teams.find(x=>x.ids.includes(String(t?.id||'')));els.drawerBody.innerHTML=`<div class="pickergrid"><div><label class="label">Division</label><select id="playerDivision">${state.divisions.map(d=>`<option value="${d.id}" ${String(d.id)===String(myDiv)?'selected':''}>${esc(d.title)}</option>`).join('')}</select></div><div><label class="label">Team</label><select id="playerTeam"><option value="">All teams</option>${teams.map(x=>`<option value="${escAttr(x.ids.join(','))}" ${myGroup===x?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div style="grid-column:1/-1"><label class="label">Search</label><input id="playerSearch" type="search" placeholder="Player name or jersey"></div></div><div id="playerPickerStatus" class="muted" style="margin:8px 0"></div><div id="playerPickerList" class="pickerlist"></div>`;const rebuildTeams=()=>{const d=$('#playerDivision').value,opts=playerTeamOptions(d);$('#playerTeam').innerHTML='<option value="">All teams</option>'+opts.map(x=>`<option value="${escAttr(x.ids.join(','))}">${esc(x.title)}</option>`).join('');loadPlayerPicker()};$('#playerDivision').onchange=rebuildTeams;$('#playerTeam').onchange=loadPlayerPicker;$('#playerSearch').oninput=renderPlayerPicker;await loadPlayerPicker()}
function extractStandingRows(body){const roots=[],seen=new Set();function walk(v,depth=0){if(v==null||depth>5)return;if(Array.isArray(v)){if(v.length&&v.some(x=>x&&typeof x==='object'&&!Array.isArray(x)))roots.push(v);for(const x of v.slice(0,5))walk(x,depth+1);return}if(typeof v!=='object'||seen.has(v))return;seen.add(v);for(const [k,x] of Object.entries(v)){if(['data','players','standings','rows','results','items','skaters','goalies','entries'].includes(k))walk(x,depth+1)}for(const x of Object.values(v))if(x&&typeof x==='object')walk(x,depth+1)}walk(body);const score=a=>a.reduce((n,r)=>n+(r&&(r.player||r.skater||r.goalie||r.firstName||r.lastName||r.name||r.title||r.stats)?1:0),0);return roots.sort((a,b)=>score(b)-score(a)||b.length-a.length)[0]||[]}
function normalizePlayerResponse(body,kind,divisionId){return extractStandingRows(body).map(r=>normalizePlayer(r,kind,divisionId)).filter(p=>p.id&&p.name)}
async function rosterFallback(teamIds,divisionId){for(const teamId of teamIds){const games=state.games.filter(g=>hasTeam(g,teamId)).sort((a,b)=>gameDate(b)-gameDate(a));for(const g of games.slice(0,4)){try{const u=`https://firestore.googleapis.com/v1/projects/gamesheet-production/databases/(default)/documents/seasons/${state.seasonId}/games/${g.gameId}`,d=firestoreData(await fetchJson(u)),side=String(g.home?.id)===String(teamId)?'home':'visitor',team=g[side]||{},players=d?.data?.[side]?.lineup?.players||[];if(players.length)return players.map(p=>normalizePlayer({player:p,team,division:team.division},String(p.position||'').toLowerCase().includes('goalie')?'goalie':'skater',divisionId)).filter(x=>x.id&&x.name)}catch(e){console.warn('Roster fallback failed for game',g.gameId,e)}}}return[]}
async function loadPlayerPicker(){const d=$('#playerDivision')?.value,teamIds=String($('#playerTeam')?.value||'').split(',').filter(Boolean);if(!d)return;$('#playerPickerStatus').textContent='Loading players…';try{const key=`${state.seasonId}:${d}:${teamIds.join(',')||'all'}`;if(!state.playerCache[key]){const base=`?limit=500&offset=0&division=${encodeURIComponent(d)}&gameType=regular_season`,[sk,go]=await Promise.allSettled([fetchJson(`${API}/players/standings/${state.seasonId}${base}&sort=-pts`),fetchJson(`${API}/goalies/standings/${state.seasonId}${base}&sort=gaa`)]),rows=[];if(sk.status==='fulfilled')rows.push(...normalizePlayerResponse(sk.value,'skater',d));if(go.status==='fulfilled')rows.push(...normalizePlayerResponse(go.value,'goalie',d));if(teamIds.length)rows.push(...await rosterFallback(teamIds,d));let merged=dedupePlayers(rows);if(teamIds.length)merged=merged.filter(p=>!p.teamId||teamIds.includes(String(p.teamId)));state.playerCache[key]=merged}renderPlayerPicker();$('#playerPickerStatus').textContent=`${state.playerCache[key].length} players found${teamIds.length?' for selected team':''}`}catch(e){console.error(e);$('#playerPickerStatus').textContent=`Could not load players: ${e.message}`}}
function renderPlayerPicker(){const d=$('#playerDivision')?.value,teamIds=String($('#playerTeam')?.value||'').split(',').filter(Boolean),key=`${state.seasonId}:${d}:${teamIds.join(',')||'all'}`,q=String($('#playerSearch')?.value||'').toLowerCase(),favs=favPlayerMap(),list=(state.playerCache[key]||[]).filter(p=>!q||`${p.name} ${p.teamTitle} ${p.number}`.toLowerCase().includes(q));$('#playerPickerList').innerHTML=list.map(p=>`<div class="pickrow">${logo({title:p.teamTitle,logo:p.teamLogo,abbr:p.teamAbbr},'xs')}<div><div class="pn">${esc(p.name)} ${p.number?`#${esc(p.number)}`:''}</div><div class="pm">${esc(p.teamTitle||'')} · ${esc(p.position||pretty(p.kind))}</div></div><button class="star ${favs[p.id]?'active':''}" data-pick="${escAttr(p.id)}" title="${favs[p.id]?'Unfollow':'Follow'} player">${favs[p.id]?'★':'☆'}</button></div>`).join('')||'<div class="empty">No matching players were returned. Try another team or division.</div>';$('#playerPickerList').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const p=(state.playerCache[key]||[]).find(x=>x.id===b.dataset.pick);if(!p)return;const m=favPlayerMap();if(m[p.id])delete m[p.id];else m[p.id]=p;saveFavPlayerMap(m);renderPlayerPicker()})}''', 'player picker')

